diff --git a/scripts/test-executor-profiles.js b/scripts/test-executor-profiles.js
index 3178834..ae5b8f6 100644
--- a/scripts/test-executor-profiles.js
+++ b/scripts/test-executor-profiles.js
@@ -185,4 +185,31 @@ for (const forbidden of ['signature', 'private', 'raw_output', 'env', 'command',
 }
 assert.equal(replay.model_status, 'unknown');

+// Telemetry that arrives trusted but carries no model is still a missing observation.
+// It must stay unknown at every layer -- including for a profile that pins no model,
+// where a recorded observation would otherwise be reported as passed.
+const unpinned = { ...copy(codex), model: null };
+for (const observation of [{}, { model: null }, { model: '' }]) {
+  const telemetry = { ...observation, trusted: true, duration_ms: 1200, tokens: 4096, cost: { amount: 0.25, unit: 'usd', source: 'adapter' } };
+  for (const profile of [local, unpinned]) {
+    assert.deepEqual(profiles.evaluateModelProof(profile, telemetry), {
+      requested_model: profile.model === null ? 'default' : profile.model,
+      observed_model: null,
+      status: 'unknown',
+      reason_code: 'MODEL_OBSERVATION_MISSING',
+    });
+    const state = profiles.missionControlExecutorState({ profile, observation: telemetry, wrapper: null });
+    assert.equal(state.observed_model, null);
+    assert.equal(state.model_status, 'unknown');
+    assert.equal(state.model_reason_code, 'MODEL_OBSERVATION_MISSING');
+    // The rest of the trusted telemetry still lands, so the unknown is about the model alone.
+    assert.equal(state.duration_status, 'known');
+    assert.equal(state.tokens_status, 'known');
+    const unknownReplay = profiles.publicExecutorReplay({ profile, observation: telemetry, wrapper: null });
+    assert.equal(unknownReplay.observed_model, null);
+    assert.equal(unknownReplay.model_status, 'unknown');
+    assert.equal(unknownReplay.model_reason_code, 'MODEL_OBSERVATION_MISSING');
+  }
+}
+
 process.stdout.write('Executor profiles passed: strict profiles, canonical digests, literal invocations, bound receipts, and honest model proof.\n');

diff --git a/scripts/test-executor-profiles.js b/scripts/test-executor-profiles.js
index 3178834..3dcdad0 100644
--- a/scripts/test-executor-profiles.js
+++ b/scripts/test-executor-profiles.js
@@ -185,4 +185,54 @@ for (const forbidden of ['signature', 'private', 'raw_output', 'env', 'command',
 }
 assert.equal(replay.model_status, 'unknown');

+// Regression: an executor profile whose observed-model telemetry is missing stays
+// unknown at every layer. Neither a trusted observation, a verified receipt, nor a
+// profile that pins no model may promote an absent observation into a match.
+const modelBlind = [
+  undefined,
+  {},
+  { trusted: true },
+  { model: '', trusted: true },
+  { model: null, trusted: true },
+  { model: 42, trusted: true },
+];
+const unpinned = legacy[0];
+for (const observation of modelBlind) {
+  for (const profile of [local, unpinned]) {
+    const label = `${profile.profile_id} / ${JSON.stringify(observation) || 'undefined'}`;
+    const missing = profiles.evaluateModelProof(profile, observation);
+    assert.equal(missing.status, 'unknown', label);
+    assert.equal(missing.observed_model, null, label);
+    assert.equal(missing.reason_code, 'MODEL_OBSERVATION_MISSING', label);
+  }
+}
+
+const modelBlindTelemetry = Object.freeze({
+  trusted: true,
+  cost: Object.freeze({ amount: 0.5, unit: 'usd', source: 'adapter' }),
+  duration_ms: 1200,
+  tokens: 4096,
+});
+const verification = profiles.verifyForkReceiptWrapper(wrapper, { publicKey, expected: wrapperInput });
+assert.equal(verification.status, 'verified');
+const blindState = profiles.missionControlExecutorState({
+  profile: local, observation: modelBlindTelemetry, wrapper, verification,
+});
+assert.equal(blindState.receipt_status, 'verified');
+assert.equal(blindState.cost_status, 'known');
+assert.equal(blindState.duration_status, 'known');
+assert.equal(blindState.tokens_status, 'known');
+assert.equal(blindState.requested_model, local.model);
+assert.equal(blindState.observed_model, null);
+assert.equal(blindState.model_status, 'unknown');
+assert.equal(blindState.model_reason_code, 'MODEL_OBSERVATION_MISSING');
+
+const blindReplay = profiles.publicExecutorReplay({
+  profile: local, observation: modelBlindTelemetry, wrapper, verification,
+});
+assert.equal(blindReplay.receipt_status, 'verified');
+assert.equal(blindReplay.observed_model, null);
+assert.equal(blindReplay.model_status, 'unknown');
+assert.equal(blindReplay.model_reason_code, 'MODEL_OBSERVATION_MISSING');
+
 process.stdout.write('Executor profiles passed: strict profiles, canonical digests, literal invocations, bound receipts, and honest model proof.\n');

