diff --git a/scripts/test-executor-profiles.js b/scripts/test-executor-profiles.js
index 3178834..8f6e6f6 100644
--- a/scripts/test-executor-profiles.js
+++ b/scripts/test-executor-profiles.js
@@ -185,4 +185,45 @@ for (const forbidden of ['signature', 'private', 'raw_output', 'env', 'command',
 }
 assert.equal(replay.model_status, 'unknown');

+// Regression: an observation that carries telemetry but no usable model must stay
+// unknown on every surface. A verified receipt proves the run happened, never that
+// the requested model ran, so it may not upgrade the model proof to a match.
+const missingModelObservations = [
+  null,
+  undefined,
+  {},
+  { trusted: true },
+  { model: null, trusted: true },
+  { model: '', trusted: true },
+  { trusted: true, duration_ms: 1200, tokens: 4096, cost: { amount: 0, unit: 'usd', source: 'local' } },
+];
+const verifiedReceipt = profiles.verifyForkReceiptWrapper(wrapper, { publicKey, expected: wrapperInput });
+assert.equal(verifiedReceipt.status, 'verified');
+for (const [index, observation] of missingModelObservations.entries()) {
+  const where = `missing-model observation #${index}`;
+  for (const profile of [local, ...profiles.synthesizeLegacyExecutors(['codex'])]) {
+    assert.deepEqual(profiles.evaluateModelProof(profile, observation), {
+      requested_model: profile.model === null ? 'default' : profile.model,
+      observed_model: null,
+      status: 'unknown',
+      reason_code: 'MODEL_OBSERVATION_MISSING',
+    }, where);
+  }
+
+  const state = profiles.missionControlExecutorState({
+    profile: local, observation, wrapper, verification: verifiedReceipt,
+  });
+  assert.equal(state.receipt_status, 'verified', where);
+  assert.equal(state.model_status, 'unknown', where);
+  assert.equal(state.model_reason_code, 'MODEL_OBSERVATION_MISSING', where);
+  assert.equal(state.observed_model, null, where);
+
+  const unknownReplay = profiles.publicExecutorReplay({
+    profile: local, observation, wrapper, verification: verifiedReceipt,
+  });
+  assert.equal(unknownReplay.model_status, 'unknown', where);
+  assert.equal(unknownReplay.observed_model, null, where);
+  assert(!JSON.stringify(unknownReplay).includes('MATCHED'), `${where} replay claimed a model match`);
+}
+
 process.stdout.write('Executor profiles passed: strict profiles, canonical digests, literal invocations, bound receipts, and honest model proof.\n');

diff --git a/scripts/test-executor-profiles.js b/scripts/test-executor-profiles.js
index 3178834..6e0daba 100644
--- a/scripts/test-executor-profiles.js
+++ b/scripts/test-executor-profiles.js
@@ -185,4 +185,40 @@ for (const forbidden of ['signature', 'private', 'raw_output', 'env', 'command',
 }
 assert.equal(replay.model_status, 'unknown');

+// Regression: telemetry that arrives with every other fact but no observed model
+// stays unknown on every surface. A verified receipt and trusted cost, duration,
+// and token counts are facts about the run, not about model identity, so they
+// must never promote a missing observation into a reported match.
+const verification = profiles.verifyForkReceiptWrapper(wrapper, { publicKey, expected: wrapperInput });
+assert.equal(verification.status, 'verified');
+const telemetry = { trusted: true, source: 'codex-jsonl', duration_ms: 1000, tokens: 900,
+  cost: { amount: 0.42, unit: 'usd', source: 'codex-jsonl' } };
+// A null-model profile is the only shape that can pass on observation alone, so
+// missing telemetry must be rejected before that branch is ever reached.
+const nullModel = legacy.find((entry) => entry.model === null);
+for (const absent of [{}, { model: null }, { model: '' }, { model: { id: 'qwen3-coder:30b' } }]) {
+  const observation = { ...telemetry, ...absent };
+  const label = JSON.stringify(absent);
+  assert.deepEqual(profiles.evaluateModelProof(local, observation), {
+    requested_model: local.model, observed_model: null,
+    status: 'unknown', reason_code: 'MODEL_OBSERVATION_MISSING',
+  }, label);
+  const state = profiles.missionControlExecutorState({ profile: local, observation, wrapper, verification });
+  assert.equal(state.observed_model, null, label);
+  assert.equal(state.model_status, 'unknown', label);
+  assert.equal(state.model_reason_code, 'MODEL_OBSERVATION_MISSING', label);
+  // The surrounding facts are known, so 'unknown' is a claim about the model alone.
+  assert.equal(state.receipt_status, 'verified', label);
+  assert.equal(state.cost_status, 'known', label);
+  assert.equal(state.duration_status, 'known', label);
+  assert.equal(state.tokens_status, 'known', label);
+  const missingReplay = profiles.publicExecutorReplay({ profile: local, observation, wrapper, verification });
+  assert.equal(missingReplay.observed_model, null, label);
+  assert.equal(missingReplay.model_status, 'unknown', label);
+  assert.deepEqual(profiles.evaluateModelProof(nullModel, observation), {
+    requested_model: 'default', observed_model: null,
+    status: 'unknown', reason_code: 'MODEL_OBSERVATION_MISSING',
+  }, label);
+}
+
 process.stdout.write('Executor profiles passed: strict profiles, canonical digests, literal invocations, bound receipts, and honest model proof.\n');

diff --git a/test.js b/test.js
index e303a46..3f3852a 100644
--- a/test.js
+++ b/test.js
@@ -193,6 +193,42 @@ test('clearQueue', async t => {
 	t.is(limit.pendingCount, 0);
 });

+test('clearQueue leaves the active promise untouched and drops every queued function', async t => {
+	const limit = pLimit(1);
+	let queuedRunCount = 0;
+
+	const runningPromise = limit(async () => {
+		await delay(50);
+		return 'active';
+	});
+
+	const pendingPromises = Array.from({length: 3}, () => limit(async () => {
+		queuedRunCount++;
+		await delay(10);
+	}));
+
+	await Promise.resolve();
+	t.is(limit.activeCount, 1);
+	t.is(limit.pendingCount, 3);
+
+	t.is(limit.clearQueue(), undefined);
+
+	// The running function keeps its slot; only the queue is emptied.
+	t.is(limit.activeCount, 1);
+	t.is(limit.pendingCount, 0);
+	t.is(await runningPromise, 'active');
+
+	// Cleared functions are never invoked and their promises stay pending by default.
+	const sentinel = Symbol('pending');
+	t.is(await Promise.race([...pendingPromises, delay(50, sentinel)]), sentinel);
+	t.is(queuedRunCount, 0);
+
+	// The public API is unchanged, so the limit still accepts new work.
+	t.is(limit.activeCount, 0);
+	t.is(await limit(() => 'after clear'), 'after clear');
+	t.is(limit.concurrency, 1);
+});
+
 // Node.js 20 has a bug where DOMException is not properly handled by AVA's `throwsAsync`.
 const testClearQueueRejects = process.versions.node.startsWith('20.') ? test.skip : test;

diff --git a/test.js b/test.js
index e303a46..38dd0d4 100644
--- a/test.js
+++ b/test.js
@@ -193,6 +193,45 @@ test('clearQueue', async t => {
 	t.is(limit.pendingCount, 0);
 });

+test('clearQueue keeps the active promise and discards every queued function by default', async t => {
+	const limit = pLimit(1);
+	const started = [];
+
+	const activePromise = limit(async () => {
+		started.push('active');
+		await delay(50);
+		return 'active result';
+	});
+
+	const queuedPromises = ['one', 'two', 'three'].map(name => limit(async () => {
+		started.push(name);
+		return name;
+	}));
+
+	await Promise.resolve();
+	t.is(limit.activeCount, 1);
+	t.is(limit.pendingCount, 3);
+
+	// Public API is unchanged: `clearQueue()` takes no arguments and returns nothing.
+	t.is(limit.clearQueue(), undefined);
+
+	// The running function is untouched, only the queue is emptied.
+	t.is(limit.activeCount, 1);
+	t.is(limit.pendingCount, 0);
+	t.is(await activePromise, 'active result');
